CREATE TABLE rr.intake (workspace_id uuid NOT NULL, case_id uuid NOT NULL, intake_id uuid NOT NULL, state text NOT NULL CHECK(state IN ('RECEIVING','VALIDATION_PENDING','VALIDATING','VALIDATED','ACCEPTED','REJECTED','LOST','EXPIRED')), first_received_at timestamptz(6) NOT NULL, expires_at timestamptz(6) NOT NULL, temporary_handle uuid NOT NULL, received_bytes bigint NOT NULL CHECK(received_bytes BETWEEN 0 AND 20971520), slot_held boolean NOT NULL, last_error_code rr.code, PRIMARY KEY(workspace_id,case_id,intake_id), FOREIGN KEY(workspace_id,case_id) REFERENCES rr.case_record, CHECK(expires_at>=first_received_at AND expires_at<=first_received_at+interval '24 hours'), created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0));

CREATE TABLE rr.input_version (workspace_id uuid NOT NULL, case_id uuid NOT NULL, input_version_id uuid NOT NULL, ordinal bigint NOT NULL CHECK(ordinal>0), intake_id uuid NOT NULL, normalizer_version rr.code NOT NULL, provider_account rr.opaque_id NOT NULL, provider_sandbox rr.opaque_id NOT NULL, app_system rr.opaque_id NOT NULL, app_environment rr.opaque_id NOT NULL, context rr.object NOT NULL, context_digest rr.digest NOT NULL, validation_system_ms bigint NOT NULL CHECK(validation_system_ms>=0), provider_role text GENERATED ALWAYS AS ('provider') STORED, application_role text GENERATED ALWAYS AS ('application') STORED, PRIMARY KEY(workspace_id,case_id,input_version_id), UNIQUE(workspace_id,case_id,ordinal), UNIQUE(workspace_id,case_id,intake_id), FOREIGN KEY(workspace_id,case_id,intake_id) REFERENCES rr.intake, created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE rr.artifact (workspace_id uuid NOT NULL, case_id uuid NOT NULL, input_version_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('provider','application')), raw_bytes bytea NOT NULL CHECK(octet_length(raw_bytes)<=10485760), sha256 rr.digest NOT NULL, logical_records bigint NOT NULL CHECK(logical_records BETWEEN 0 AND 10000), PRIMARY KEY(workspace_id,case_id,input_version_id,role), FOREIGN KEY(workspace_id,case_id,input_version_id) REFERENCES rr.input_version DEFERRABLE INITIALLY DEFERRED, created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);

ALTER TABLE rr.input_version ADD CONSTRAINT input_provider_artifact FOREIGN KEY(workspace_id,case_id,input_version_id,provider_role) REFERENCES rr.artifact(workspace_id,case_id,input_version_id,role) DEFERRABLE INITIALLY DEFERRED;

ALTER TABLE rr.input_version ADD CONSTRAINT input_application_artifact FOREIGN KEY(workspace_id,case_id,input_version_id,application_role) REFERENCES rr.artifact(workspace_id,case_id,input_version_id,role) DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE rr.provider_payment (workspace_id uuid NOT NULL, case_id uuid NOT NULL, input_version_id uuid NOT NULL, payment_id rr.opaque_id NOT NULL, source_ordinal bigint NOT NULL CHECK(source_ordinal>0), status rr.source_status, capture_method rr.source_status, amount rr.minor_amount, amount_received rr.minor_amount, amount_capturable rr.minor_amount, currency rr.opaque_id, latest_charge_id rr.opaque_id, observed_start timestamptz(6), observed_end timestamptz(6), clock_error_us bigint CHECK(clock_error_us>=0), presence rr.object NOT NULL, CHECK(observed_start IS NULL OR observed_end IS NULL OR observed_end>=observed_start), PRIMARY KEY(workspace_id,case_id,input_version_id,payment_id), FOREIGN KEY(workspace_id,case_id,input_version_id) REFERENCES rr.input_version, created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE rr.provider_charge (workspace_id uuid NOT NULL, case_id uuid NOT NULL, input_version_id uuid NOT NULL, charge_id rr.opaque_id NOT NULL, source_ordinal bigint NOT NULL CHECK(source_ordinal>0), payment_intent_id rr.opaque_id, status rr.source_status, paid boolean, captured boolean, disputed boolean, amount rr.minor_amount, amount_captured rr.minor_amount, amount_refunded rr.minor_amount, currency rr.opaque_id, actual_method_type rr.source_status, observed_start timestamptz(6), observed_end timestamptz(6), clock_error_us bigint CHECK(clock_error_us>=0), presence rr.object NOT NULL, CHECK(observed_start IS NULL OR observed_end IS NULL OR observed_end>=observed_start), PRIMARY KEY(workspace_id,case_id,input_version_id,charge_id), FOREIGN KEY(workspace_id,case_id,input_version_id) REFERENCES rr.input_version, created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE rr.application_order (workspace_id uuid NOT NULL, case_id uuid NOT NULL, input_version_id uuid NOT NULL, order_id rr.opaque_id NOT NULL, source_ordinal bigint NOT NULL CHECK(source_ordinal>0), payment_reference rr.opaque_id, payment_state rr.source_status, raw_payment_state rr.source_status, expected_amount rr.minor_amount, expected_currency rr.opaque_id, expectation_revision rr.opaque_id, observed_start timestamptz(6), observed_end timestamptz(6), clock_error_us bigint CHECK(clock_error_us>=0), presence rr.object NOT NULL, CHECK(observed_start IS NULL OR observed_end IS NULL OR observed_end>=observed_start), PRIMARY KEY(workspace_id,case_id,input_version_id,order_id), FOREIGN KEY(workspace_id,case_id,input_version_id) REFERENCES rr.input_version, created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE rr.command_effect (account_id uuid NOT NULL REFERENCES rr.account, account_generation bigint NOT NULL CHECK(account_generation>0), action rr.code NOT NULL, client_key rr.code NOT NULL, fingerprint_version rr.code NOT NULL, fingerprint rr.digest NOT NULL, effect_id uuid NOT NULL, effect_kind rr.code NOT NULL, outcome_code rr.code NOT NULL, PRIMARY KEY(account_id,account_generation,action,client_key), created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE rr.quota_allocation (workspace_id uuid NOT NULL, case_id uuid NOT NULL, allocation_id uuid NOT NULL, resource_kind rr.code NOT NULL, resource_id uuid NOT NULL, codec_version rr.code NOT NULL, state text NOT NULL CHECK(state IN ('RESERVED','CHARGED','RELEASING')), reserved_bytes bigint NOT NULL CHECK(reserved_bytes>=0), charged_bytes bigint NOT NULL CHECK(charged_bytes>=0), PRIMARY KEY(workspace_id,allocation_id), UNIQUE(workspace_id,case_id,allocation_id), UNIQUE(workspace_id,case_id,resource_kind,resource_id), FOREIGN KEY(workspace_id,case_id) REFERENCES rr.case_record, CHECK((state='RESERVED' AND charged_bytes=0) OR (state='CHARGED' AND reserved_bytes=0) OR state='RELEASING'), created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0));

CREATE TABLE rr.analysis_run (workspace_id uuid NOT NULL, case_id uuid NOT NULL, run_id uuid NOT NULL, input_id uuid NOT NULL, rule_version rr.code NOT NULL, currency_version rr.code NOT NULL, normalizer_version rr.code NOT NULL, config rr.object NOT NULL, config_digest rr.digest NOT NULL, reference_at timestamptz(6) NOT NULL, requested_at timestamptz(6) NOT NULL, deadline_at timestamptz(6) NOT NULL, operational_phase text NOT NULL CHECK(operational_phase IN ('QUEUED','RUNNING','RETRY_WAIT','PUBLISHED','FAILED','EXPIRED','SUPPRESSED')), terminal_at timestamptz(6), result_reservation_id uuid NOT NULL, validation_system_ms bigint NOT NULL CHECK(validation_system_ms>=0), PRIMARY KEY(workspace_id,case_id,run_id), FOREIGN KEY(workspace_id,case_id,input_id) REFERENCES rr.input_version, FOREIGN KEY(workspace_id,case_id,result_reservation_id) REFERENCES rr.quota_allocation(workspace_id,case_id,allocation_id), CHECK(deadline_at>=requested_at), CHECK((terminal_at IS NULL)=(operational_phase IN ('QUEUED','RUNNING','RETRY_WAIT'))), created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0));

CREATE TABLE rr.run_attempt (workspace_id uuid NOT NULL, case_id uuid NOT NULL, run_id uuid NOT NULL, attempt_no bigint NOT NULL CHECK(attempt_no BETWEEN 1 AND 2), attempt_token uuid NOT NULL, runtime_id uuid NOT NULL REFERENCES rr.runtime_incarnation, state rr.code NOT NULL, started_at timestamptz(6) NOT NULL, stopped_at timestamptz(6), output_bytes bigint NOT NULL CHECK(output_bytes BETWEEN 0 AND 67108864), failure_code rr.code, PRIMARY KEY(workspace_id,case_id,run_id,attempt_no), UNIQUE(workspace_id,case_id,run_id,attempt_token), FOREIGN KEY(workspace_id,case_id,run_id) REFERENCES rr.analysis_run, CHECK(stopped_at IS NULL OR stopped_at>=started_at), created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0));

CREATE TABLE rr.output_manifest (workspace_id uuid NOT NULL, case_id uuid NOT NULL, run_id uuid NOT NULL, attempt_no bigint NOT NULL CHECK(attempt_no BETWEEN 1 AND 2), sealed boolean NOT NULL DEFAULT false, input_count bigint NOT NULL CHECK(input_count>=0), assessed_count bigint NOT NULL CHECK(assessed_count>=0), unassessed_count bigint NOT NULL CHECK(unassessed_count>=0), finding_count bigint NOT NULL CHECK(finding_count>=0), encoded_bytes bigint NOT NULL CHECK(encoded_bytes BETWEEN 0 AND 67108864), digest rr.digest, PRIMARY KEY(workspace_id,case_id,run_id,attempt_no), UNIQUE(workspace_id,case_id,run_id,attempt_no,sealed), FOREIGN KEY(workspace_id,case_id,run_id,attempt_no) REFERENCES rr.run_attempt, CHECK(NOT sealed OR digest IS NOT NULL), created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0));

CREATE TABLE rr.finding (workspace_id uuid NOT NULL, case_id uuid NOT NULL, run_id uuid NOT NULL, attempt_no bigint NOT NULL CHECK(attempt_no BETWEEN 1 AND 2), finding_id uuid NOT NULL, rule_id rr.code NOT NULL, classification rr.code NOT NULL, subject_kind rr.code NOT NULL, subject_id rr.opaque_id NOT NULL, source_refs rr.object NOT NULL, explanation_code rr.code NOT NULL, safe_values rr.object NOT NULL, encoded_bytes bigint NOT NULL CHECK(encoded_bytes BETWEEN 0 AND 67108864), PRIMARY KEY(workspace_id,case_id,run_id,attempt_no,finding_id), FOREIGN KEY(workspace_id,case_id,run_id,attempt_no) REFERENCES rr.output_manifest, created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE rr.publication (workspace_id uuid NOT NULL, case_id uuid NOT NULL, run_id uuid NOT NULL, attempt_no bigint NOT NULL, required_sealed boolean GENERATED ALWAYS AS (true) STORED, published_at timestamptz(6) NOT NULL, semantic_digest rr.digest NOT NULL, PRIMARY KEY(workspace_id,case_id,run_id), FOREIGN KEY(workspace_id,case_id,run_id) REFERENCES rr.analysis_run, FOREIGN KEY(workspace_id,case_id,run_id,attempt_no,required_sealed) REFERENCES rr.output_manifest(workspace_id,case_id,run_id,attempt_no,sealed), created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE TABLE rr.case_execution_slot (workspace_id uuid NOT NULL, case_id uuid NOT NULL, owner_run_id uuid, owner_attempt_no bigint, runtime_id uuid REFERENCES rr.runtime_incarnation, token uuid, held_since timestamptz(6), PRIMARY KEY(workspace_id,case_id), FOREIGN KEY(workspace_id,case_id) REFERENCES rr.case_record, FOREIGN KEY(workspace_id,case_id,owner_run_id,owner_attempt_no) REFERENCES rr.run_attempt, CHECK(num_nonnulls(owner_run_id,owner_attempt_no,runtime_id,token,held_since) IN (0,5)), created_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, row_version bigint NOT NULL DEFAULT 1 CHECK(row_version>0));

CREATE UNIQUE INDEX one_active_run ON rr.analysis_run(workspace_id,case_id) WHERE terminal_at IS NULL;

CREATE INDEX run_input ON rr.analysis_run(workspace_id,case_id,input_id); CREATE INDEX run_reservation ON rr.analysis_run(workspace_id,case_id,result_reservation_id); CREATE INDEX run_runtime ON rr.run_attempt(runtime_id); CREATE INDEX slot_runtime ON rr.case_execution_slot(runtime_id); CREATE INDEX slot_attempt ON rr.case_execution_slot(workspace_id,case_id,owner_run_id,owner_attempt_no);

CREATE INDEX run_history ON rr.analysis_run(workspace_id,case_id,requested_at DESC,run_id DESC); CREATE INDEX run_admission ON rr.analysis_run(operational_phase,requested_at,run_id) WHERE terminal_at IS NULL;

CREATE INDEX intake_expiry ON rr.intake(expires_at,workspace_id,case_id,intake_id) WHERE slot_held=true; CREATE INDEX allocation_state ON rr.quota_allocation(workspace_id,state,allocation_id); CREATE INDEX command_effect_lookup ON rr.command_effect(account_id,account_generation,effect_kind,effect_id);

CREATE INDEX order_reference ON rr.application_order(workspace_id,case_id,input_version_id,payment_reference); CREATE INDEX charge_payment ON rr.provider_charge(workspace_id,case_id,input_version_id,payment_intent_id);
